        private final int[] minEdgeWeight;
        private final boolean[] inMST;

        VertexState(int vertexCount) {
            parent = new int[vertexCount];
            minEdgeWeight = new int[vertexCount];
            inMST = new boolean[vertexCount];
            Arrays.fill(minEdgeWeight, Integer.MAX_VALUE);
        }

        void setSource(int vertex) {
            minEdgeWeight[vertex] = 0;
            parent[vertex] = -1;
        }

        int nextVertex() {
            int min = Integer.MAX_VALUE;
            int minVertex = -1;
            for (int v = 0; v < minEdgeWeight.length; v++) {
                if (!inMST[v] && minEdgeWeight[v] < min) {
                    min = minEdgeWeight[v];
                    minVertex = v;
                }
            }
            return minVertex;
        }

        void include(int vertex) {
            inMST[vertex] = true;
        }

        void relaxEdge(Edge edge) {
            if (!inMST[edge.to] && edge.weight < minEdgeWeight[edge.to]) {
                parent[edge.to] = edge.from;
                minEdgeWeight[edge.to] = edge.weight;
            }
        }

        List<Edge> buildEdges(int startVertex) {
            List<Edge> edges = new ArrayList<>();
            for (int i = 0; i < parent.length; i++) {
                if (i != startVertex) {
                    edges.add(new Edge(parent[i], i, minEdgeWeight[i]));
                }
            }
            return edges;
        }
    }
}

import java.util.Collections;
import java.util.List;

class MstResult {
    private final List<Edge> edges;
    private final int totalWeight;

    MstResult(List<Edge> edges) {
        this.edges = Collections.unmodifiableList(edges);
        this.totalWeight = edges.stream().mapToInt(e -> e.weight).sum();
    }

    List<Edge> edges() {
        return edges;
    }

    int totalWeight() {
        return totalWeight;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof MstResult)) return false;
        MstResult other = (MstResult) obj;
        return totalWeight == other.totalWeight && edges.equals(other.edges);
    }

    @Override
    public int hashCode() {
        return 31 * totalWeight + edges.hashCode();
    }
}
